        let err = execute_soracloud_fhe_job_with_residual_bounds(
            &params,
            &evaluation_keys,
            &job,
            std::slice::from_ref(&input),
            &[1],
        )
        .expect_err("residual-bound full-bootstrap execution must require artifacts");
