        isi::AdvanceSoracloudRollout {
            service_name: service_name.clone(),
            rollout_handle: rollout_handle.clone(),
            healthy: false,
            promote_to_percent: None,
            governance_tx_hash,
            provenance: rollout_provenance(
                &service_name,
                &rollout_handle,
                false,
                None,
                governance_tx_hash,
            ),
        }
        .execute(&ALICE_ID, &mut stx)?;

        stx.apply();
        state_block.commit()?;

        let view = state.view();
